/// <summary>
/// MET extensions MPJ_27582 for the <c>SalesInvoiceJournalPost</c> class.
/// </summary>
[ExtensionOf(classStr(SalesInvoiceJournalPost))]
internal final class METSalesInvoiceJournalPost_Extension
{
    #ISOCountryRegionCodes
    private METDiscountClaimHelper discountClaimHelper;
     
}

Method.Source:
    /// Task 96965: Generate invoices for sales orders, validate account allocation.
    public void init()
    {
        next init();

        discountClaimHelper = new METDiscountClaimHelper();
    }

    /// <summary>
    /// Posts line
    /// </summary>
    protected void postLines()
    {
        next postLines();

        //CS-CB789_InvoicePosting
        this.metPostAdditionalCOGS();
        //CE-CB789_InvoicePosting

        discountClaimHelper.setPostLinesParameters(ledgerVoucher);
        discountClaimHelper.postDiscountClaimAccrualJournal();
    }

    /// <summary>
    /// Posts line discount
    /// </summary>
    protected void postLineDiscount()
    {
        next postLineDiscount();

        if (!this.canSkipPostLineDiscount() && salesLine.SalesQty > 0)
        {
            this.METCreateDiscountClaimAndAccrualJournal();
        }
    }

    private void METCreateDiscountClaimAndAccrualJournal()
    {
        discountClaimHelper.setDiscountPostParameters(
            updateNow,
            this.inventTable.ItemId,
            custInvoiceTrans.InventDimId,
            custInvoiceJour.InvoiceId,
            salesLine);

        discountClaimHelper.distributeDiscountClaim();
    }

    /// <summary>
    /// Posts after line
    /// </summary>
    protected void afterLinePost()
    {
        next afterLinePost();

        if (!this.isProforma())
        {
            if (salesLine.RevRecRevenueScheduleID)
            {
                info("@GlobalUnifiedPricing:UseStandardSalesLineAmountPostingWithRevRecRevenueScheduleIDSet");
            }
            else
            {
                this.METPostSalesTradeAgreement();
                this.METPostMarginComponentAdjustments();
            }
        }
    }

    /// <summary>
    /// Additional COGS postings for price components flagged with AdditionalPostingsToCOGS.
    /// Entry 1: SalesRevenue account (getLedgerDimensionLineAmount) — DEBIT
    /// Entry 2: SalesConsump account (METGetLedgerDimensionAccountConsumption) — CREDIT
    /// </summary> 
    private void metPostAdditionalCOGS()
    {
        METSalesLinePriceComponent  metSalesLinePriceComponent;
        METComponentCode            metComponentCode;
        LedgerVoucher               ledgerVoucherLocal  = this.getLedgerVoucher();
        LedgerVoucherObject         ledgerVoucherObject = ledgerVoucherLocal.findLedgerVoucherObject();
        CurrencyExchangeHelper      exchangeRateHelper  = CurrencyExchangeHelper::newExchangeDate(
                                                        Ledger::primaryLedger(CompanyInfo::findDataArea(curext()).RecId),
                                                        ledgerVoucherObject.parmAccountingDate());
        exchangeRateHelper.parmExchangeRate1(this.fixedExchRate());
        exchangeRateHelper.parmExchangeRate2(this.fixedExchRateSecondary());

        SalesParmLine salesParmLine;

        while select salesParmLine
        where salesParmLine.ParmId     == salesParmTable.ParmId
           && salesParmLine.TableRefId == salesParmTable.TableRefId
        {
            SalesLine salesLineDefaultDim = salesParmLine.salesLine();

            if (salesLineDefaultDim)
            {
                while select Value, Component, InventTransId from metSalesLinePriceComponent
                    where metSalesLinePriceComponent.InventTransId == salesLineDefaultDim.InventTransId
                join MainAccountId from metComponentCode
                    where metComponentCode.Component               == metSalesLinePriceComponent.Component
                       && metComponentCode.AdditionalPostingsToCOGS == NoYes::Yes
                       && metComponentCode.MainAccountId           != ''
                {
                    Amount value = metSalesLinePriceComponent.Value;

                    if (METSalesLinePriceComponentDetail::existComponent(salesLineDefaultDim.InventTransId, metSalesLinePriceComponent.Component))
                    {
                        value = metSalesLinePriceComponent.getTotalVendorValue();
                    }

                    Amount postingAmount = CurrencyExchange::round(salesParmLine.DeliverNow * value, salesLineDefaultDim.CurrencyCode);

                    //Bug 396152: UAT - Sales Order-Claim/Return -Disposition code 21-COGS is wrong in the Return SO
                    if (salesTable.Salestype == SalesType::ReturnItem)
                    {
                        postingAmount = -1*postingAmount;
                    }

                    // Entry 1: SalesRevenue account — CREDIT
                    LedgerDimensionAccount ledgerDimensionMerged = this.getLedgerDimensionLineAmount();
                    ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionMerged, salesLineDefaultDim.DefaultDimension);

                    LedgerVoucherTransObject ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                    ledgerVoucherObject,
                    LedgerPostingType::SalesRevenue,
                    ledgerDimensionMerged,
                    salesLineDefaultDim.CurrencyCode,
                        postingAmount * (metSalesLinePriceComponent.Component == 'Excise' ? -1 : 1),
                    exchangeRateHelper);

                    ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);

                    // Entry 2: SalesConsump account — DEBIT
                    ledgerDimensionMerged = this.METGetLedgerDimensionAccountConsumption();
                    ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionMerged, salesLineDefaultDim.DefaultDimension);

                    ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                    ledgerVoucherObject,
                    LedgerPostingType::SalesConsump,
                    ledgerDimensionMerged,
                    salesLineDefaultDim.CurrencyCode,
                        postingAmount  * (metSalesLinePriceComponent.Component == 'Excise' ? 1 : -1),
                    exchangeRateHelper);

                    ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);
                }
            }
        }
    }

    /// <summary>
    /// Posts margin component adjustments for price components flagged as Margins.
    /// Entry 1: Revenue line amount account (getLedgerDimensionLineAmount) — DEBIT
    /// Entry 2: Component MainAccount — CREDIT
    /// </summary>
    private void METPostMarginComponentAdjustments()
    {
        METSalesLinePriceComponent  METSalesLinePriceComponent;
        METComponentCode            METComponentCode;

        LedgerVoucher       ledgerVoucherLocal  = this.getLedgerVoucher();
        LedgerVoucherObject ledgerVoucherObject  = ledgerVoucherLocal.findLedgerVoucherObject();

        CurrencyExchangeHelper exchangeRateHelper = CurrencyExchangeHelper::newExchangeDate(
                                                        Ledger::primaryLedger(CompanyInfo::findDataArea(curext()).RecId),
                                                        ledgerVoucherObject.parmAccountingDate());
        exchangeRateHelper.parmExchangeRate1(this.fixedExchRate());
        exchangeRateHelper.parmExchangeRate2(this.fixedExchRateSecondary());

        while select Value, Component, InventTransId from METSalesLinePriceComponent
                join MainAccountId, AdditionalPostingsToCOGS from METComponentCode
               where METSalesLinePriceComponent.InventTransId == SalesLine.InventTransId
                  && METComponentCode.Component               == METSalesLinePriceComponent.Component
                  && METComponentCode.PriceComponent          == METPriceComponent::Margins
        {
            if (METComponentCode.MainAccountId)
            { 
                RecId ledgerDimensionId;

                if (salesTable.Salestype == SalesType::ReturnItem && ReturnDispositionCode::find(salesline.ReturnDispositionCodeId).DispositionAction == DispositionAction::CreditOnly
                && METComponentCode.AdditionalPostingsToCOGS == NoYes::Yes)
                {
                    ledgerDimensionId = this.metGetMainAccountforReturnCriteria(salesLine.inventtable());
                }
                else
                {
                    ledgerDimensionId = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountId(METComponentCode.MainAccountId);
                }

                if (ledgerDimensionId)
                {
                    Amount value = abs(METSalesLinePriceComponent.Value);

                    if (METSalesLinePriceComponentDetail::existComponent(SalesLine.InventTransId, METSalesLinePriceComponent.Component))
                    {
                        value = abs(METSalesLinePriceComponent.getTotalVendorValue());
                    }

                    Amount postingAmount = CurrencyExchange::round(updateNow * value, salesLine.CurrencyCode);

                    // Entry 1: Revenue line amount account — CREDIT
                    LedgerDimensionAccount ledgerDimensionMerged = this.getLedgerDimensionLineAmount();

                    LedgerVoucherTransObject ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                        ledgerVoucherObject,
                        LedgerPostingType::SalesRevenue,
                        ledgerDimensionMerged,
                        salesLine.CurrencyCode,
                        postingAmount,
                        exchangeRateHelper);

                    ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);

                    // Entry 2: Component MainAccount — DEBIT 
                    ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionId, salesLine.DefaultDimension);

                    ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                        ledgerVoucherObject,
                        LedgerPostingType::SalesRevenue,
                        ledgerDimensionMerged,
                        salesLine.CurrencyCode,
                        -1 * postingAmount,
                        exchangeRateHelper);

                    ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);
                }
            }
        }
    }

    /// <summary>
    /// Posts trade agreement price component for BasePrice components.
    /// Entry 1: Duty Clearing account (getLedgerDimensionLineAmount / 173011) — DEBIT
    /// Entry 2: InventPosting SalesRevenue account (440171) — CREDIT
    /// </summary>
    private void METPostSalesTradeAgreement()
    {
        METSalesLinePriceComponent  METSalesLinePriceComponent;
        METComponentCode            METComponentCode;

        select Value, Component, InventTransId from METSalesLinePriceComponent
                join MainAccountId from METComponentCode
               where METSalesLinePriceComponent.InventTransId == SalesLine.InventTransId
                  && METComponentCode.Component               == METSalesLinePriceComponent.Component
                  && METComponentCode.PriceComponent          == METPriceComponent::BasePrice;

        Amount value = abs(METSalesLinePriceComponent.Value);

        if (METSalesLinePriceComponentDetail::existComponent(SalesLine.InventTransId, METSalesLinePriceComponent.Component))
        {
            value = abs(METSalesLinePriceComponent.getTotalVendorValue());
        }

        if (METComponentCode.MainAccountId)
        {
            RecId ledgerDimensionId = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountId(METComponentCode.MainAccountId);

            if (ledgerDimensionId)
            {
                LedgerVoucher       ledgerVoucherLocal  = this.getLedgerVoucher();
                LedgerVoucherObject ledgerVoucherObject  = ledgerVoucherLocal.findLedgerVoucherObject();

                CurrencyExchangeHelper exchangeRateHelper = CurrencyExchangeHelper::newExchangeDate(
                                                                Ledger::primaryLedger(CompanyInfo::findDataArea(curext()).RecId),
                                                                ledgerVoucherObject.parmAccountingDate());
                exchangeRateHelper.parmExchangeRate1(this.fixedExchRate());
                exchangeRateHelper.parmExchangeRate2(this.fixedExchRateSecondary());

                Amount postingAmount = CurrencyExchange::round(updateNow * value, salesLine.CurrencyCode);

                // Entry 1: Duty Clearing account (173011) — DEBIT
                LedgerDimensionAccount ledgerDimensionMerged = this.getLedgerDimensionLineAmount();

                LedgerVoucherTransObject ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                        ledgerVoucherObject,
                        LedgerPostingType::SalesRevenue,
                        ledgerDimensionMerged,
                        salesLine.CurrencyCode,
                        postingAmount,
                        exchangeRateHelper);

                ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);

                // Entry 2: InventPosting SalesRevenue account (440171) — CREDIT
                LedgerDimensionDefaultAccount postingMainAccount =
                    InventPosting::accountItemLedgerDimensionFromParameters(
                        InventPostingAccountItemLedgerDimensionParameters::newFromSalesLine(
                            salesLine,
                            InventAccountType::SalesRevenue,
                            inventTable.itemGroupId(),
                            salesLine.inventDim()));

                ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(postingMainAccount, salesLine.DefaultDimension);

                ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                        ledgerVoucherObject,
                        LedgerPostingType::SalesRevenue,
                        ledgerDimensionMerged,
                        salesLine.CurrencyCode,
                        -1 * postingAmount,
                        exchangeRateHelper);

                ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);
            }
        }
    }

    /// <summary>
    /// Posts retail periodic discounts from custom MET tables in place of RetailSalesDiscountLine.
    /// </summary>
    protected void postRetailPeriodicDiscounts()
    {
        next postRetailPeriodicDiscounts();

        LedgerVoucherTransObject        ledgerPostingTransaction;
        METSalesLinePriceComponentDetail salesLinePriceComponentDetail;
        METSalesLinePriceComponent      salesLinePriceComponent;
        METComponentCode                componentCode;
        SalesPurchLineInterface         salesPurchLineInterface              = salesPurchLine.salesPurchLineInterface();
        LedgerDimensionDefaultAccount   accountDisc                         = formletterProvider.lineDiscountLedgerDimension();
        LedgerVoucherObject             ledgerVoucherObject                 = ledgerVoucher.findLedgerVoucherObject();
        int                             sign                                = this.creditDiscount() ? -1 : 1;
        DiscAmount                      metDiscAmount;

        container periodicDiscountVRefs;
        boolean   isExactBondRequiredForDiscountTransaction;

        if (salesLine.salesTable().SalesType == SalesType::ReturnItem)
        {
            sign = -1;
        }

        if (SysCountryRegionCode::isLegalEntityInCountryRegion([#isoRU]))
        {
            isExactBondRequiredForDiscountTransaction = ledgerVoucherObject.ledgerBondClient_RU() != null;
        }

        CurrencyExchangeHelper exchangeRateHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::current(), ledgerVoucherObject.parmAccountingDate());

        InventQty   invoicedNowQty = updateNow;
        AmountCur   periodicDiscountAmount, sumRevertAmount;

        LedgerDimensionDefaultAccount ledgerAccountPeriodicDisc;
        LedgerDimensionAccount        ledgerDimensionDiscountAccount, ledgerDimensionPeriodicDiscount;

        while select salesLinePriceComponentDetail
                join salesLinePriceComponent
               where salesLinePriceComponentDetail.InventTransId    == salesLine.InventTransId
                  && salesLinePriceComponent.InventTransId          == salesLinePriceComponentDetail.InventTransId
                  && salesLinePriceComponent.Component              == salesLinePriceComponentDetail.Component
            exists join componentCode
               where componentCode.Component     == salesLinePriceComponentDetail.Component
                  && componentCode.PriceComponent == METPriceComponent::Discounts
        {
            metDiscAmount = salesLinePriceComponentDetail.VendorValue;

            if (salesTable.InclTax == NoYes::yes)
            {
                metDiscAmount = salesPurchLineInterface.amountExclTax(salesLinePriceComponentDetail.VendorValue, invoicedNowQty, this.transDate, tax);
            }

            ledgerAccountPeriodicDisc       = RetailParameters::find().OfferLedgerDimension;
            ledgerDimensionPeriodicDiscount = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerAccountPeriodicDisc, salesPurchLineInterface.parmDefaultDimension());
            periodicDiscountAmount          = CurrencyExchangeHelper::amount(invoicedNowQty * metDiscAmount, salesPurchLineInterface.parmCurrencyCode());

            if (periodicDiscountAmount)
            {
                ledgerPostingTransaction = LedgerVoucherTransObject::newTransactionAmountDefault(
                    ledgerVoucherObject,
                    formletterProvider.postingTypeLineDiscount(),
                    ledgerDimensionPeriodicDiscount,
                    salesPurchLineInterface.parmCurrencyCode(),
                    periodicDiscountAmount * sign,
                    exchangeRateHelper);

                this.addTaxParentReference(ledgerPostingTransaction);
                ledgerPostingTransaction.setTaxTransRelationshipType(TaxTransRelationshipType::LineDiscount);
                ledgerPostingTransaction.parmProjLedger(this.projLedger());
                ledgerPostingTransaction.parmSourceTableId(salesPurchLine.TableId);
                ledgerPostingTransaction.parmSourceRecId(salesPurchLine.RecId);
                ledgerPostingTransaction.parmLedgerDetailLevel(LedgerDetailLevel::Detail);
                ledgerVoucher.addTrans(ledgerPostingTransaction);
                sumRevertAmount += periodicDiscountAmount;

                if (isExactBondRequiredForDiscountTransaction)
                {
                    periodicDiscountVRefs += [ledgerVoucherObject.ledgerBondClient_RU().lastVrefId()];
                }
            }
        }

        if (sumRevertAmount)
        {
            ledgerDimensionDiscountAccount = LedgerDimensionFacade::serviceCreateLedgerDimension(accountDisc, salesPurchLineInterface.parmDefaultDimension());

            ledgerPostingTransaction = LedgerVoucherTransObject::newTransactionAmountDefault(
                ledgerVoucherObject,
                formletterProvider.postingTypeLineDiscount(),
                ledgerDimensionDiscountAccount,
                salesPurchLineInterface.parmCurrencyCode(),
                -1 * sumRevertAmount * sign,
                exchangeRateHelper);

            this.addTaxParentReference(ledgerPostingTransaction);
            ledgerPostingTransaction.setTaxTransRelationshipType(TaxTransRelationshipType::LineDiscount);
            ledgerPostingTransaction.parmProjLedger(this.projLedger());
            ledgerPostingTransaction.parmSourceTableId(salesPurchLine.TableId);
            ledgerPostingTransaction.parmSourceRecId(salesPurchLine.RecId);
            ledgerPostingTransaction.parmLedgerDetailLevel(LedgerDetailLevel::Detail);
            ledgerVoucher.addTrans(ledgerPostingTransaction);

            if (isExactBondRequiredForDiscountTransaction && conLen(periodicDiscountVRefs) > 0)
            {
                LedgerBondClient_RU ledgerBondClient = ledgerVoucherObject.ledgerBondClient_RU();
                ledgerBondClient.bondVRef2Log(ledgerBondClient.lastVrefId(), periodicDiscountVRefs);
            }
        }
    }

    /// <summary>
    /// get main account for return criteria, if sales type is return item and disposition action is credit only, then get main account from invent posting with criteria of return, otherwise get main account from component code.
    /// </summary>
    /// <param name = "_inventtable">_inventtable</param>
    /// <returns>LedgerDimensionDefaultAccount</returns>
    public LedgerDimensionDefaultAccount metGetMainAccountforReturnCriteria(inventTable _inventtable)
    {
        InventPosting   inventPosting;
        MainAccountNum  mainAccountNum;
        LedgerDimensionBase     ledgerDimension;
        DimensionStorage        dimStorage;
        //    // Look for a configuration specific to the Item first, then fall back to the Item Group
        select firstOnly ledgerDimension from inventPosting
                where inventPosting.InventAccountType == InventAccountType::InventLoss
                   && ((inventPosting.ItemCode == InventPostingItemCode::Table && inventPosting.ItemRelation == _inventtable.ItemId)
                    || (inventPosting.ItemCode == InventPostingItemCode::GroupId && inventPosting.ItemRelation == _inventtable.itemGroupId())
                    || (inventPosting.ItemCode == InventPostingItemCode::All));

        return  inventPosting.ledgerDimension;
    }

    /// <summary>
    /// update shipment id and load id in custInvoiceJour table after posting the invoice.
    /// </summary>
    public void postJournalPost()
    {
        next postJournalPost();

        CustInvoiceTrans custInvoiceTransLocal;
        CustInvoiceJour  custInvoiceJourLocal = formletterJournal.TableId == tableNum(CustInvoiceJour) ? formletterJournal : custInvoiceJour;

        select firstonly custInvoiceTransLocal
            where custInvoiceTransLocal.InvoiceId == custInvoiceJourLocal.InvoiceId;


        METCustTable metCustTable = METCustTable::find(custInvoiceJourLocal.OrderAccount);

        if (WHSParameters::find().METDecoupleSalesShipmentInvoice && custInvoiceTransLocal.RecId && metCustTable.FinalizationDocument == METFinalizationDocument::None)
        {
            ttsbegin;
            custInvoiceTransLocal.metUpdateLoadIdAndShipmentId();
            ttscommit;

            SalesTable salesTableLoc = SalesTable::find(custInvoiceJourLocal.SalesId, true);

            if (salesTableLoc && salesTableLoc.METFinalisationInvoicePostingRequired)
            {
                salesTableLoc.SkipUpdate = true;
                salesTableLoc.skipBusinessEvents(true);
                salesTableLoc.METFinalisationInvoicePostingRequired = NoYes::No;
                salesTableLoc.doUpdate();

                info(strFmt("@MET:InvoicePostingFinalisationFlag", custInvoiceJourLocal.SalesId));
            }
        }
    }
